from datetime import datetime, timedelta
import re

def parse_iso(s):
    if s is None:
        return None
    s2=s
    if isinstance(s2,str) and s2.endswith('Z'):
        s2=s2[:-1]+'+00:00'
    return datetime.fromisoformat(s2)

# Login venmo and simple_note
creds = apis.supervisor.show_account_passwords(); pm={c['account_name']:c['password'] for c in creds}
venmo_access=apis.venmo.login(username='cod.smith@gmail.com', password=pm['venmo'])['access_token']
simple_access=apis.simple_note.login(username='cod.smith@gmail.com', password=pm['simple_note'])['access_token']
phone_access=apis.phone.login(username='7826309761', password=pm['phone'])['access_token']

# Latest Work Dinner note
work_meta=[]
page=0
while True:
    resp=apis.simple_note.search_notes(access_token=simple_access, query='Work Dinner', page_index=page, page_limit=20, sort_by='-updated_at')
    if not resp:
        break
    if isinstance(resp, dict) and 'message' in resp:
        raise RuntimeError(resp['message'])
    work_meta.extend(resp)
    if len(resp)<20:
        break
    page+=1

latest=max(work_meta, key=lambda n: parse_iso(n.get('updated_at')) or datetime.min)
note=apis.simple_note.show_note(note_id=latest['note_id'], access_token=simple_access)
note_updated_dt=parse_iso(note['updated_at'])

# Parse shares
shares=[]
for line in note['content'].splitlines():
    m=re.match(r"\s*-\s*([^=]+?)\s*=>\s*\$\s*([0-9]+(?:\.[0-9]+)?)\s*$", line)
    if m:
        name=m.group(1).strip()
        amt=float(m.group(2))
        shares.append({'name':name,'amount':amt,'cents':int(round(amt*100))})

# Fetch received work dinner transactions in window
min_date=(note_updated_dt - timedelta(days=3)).date().isoformat()
max_date=(note_updated_dt + timedelta(days=3)).date().isoformat()

received=[]
page=0
while True:
    resp=apis.venmo.show_transactions(access_token=venmo_access, direction='received', min_created_at=min_date, max_created_at=max_date, page_index=page, page_limit=20, sort_by='-created_at')
    if not resp:
        break
    if isinstance(resp, dict) and 'message' in resp:
        raise RuntimeError(resp['message'])
    received.extend(resp)
    if len(resp)<20:
        break
    page+=1

work_received=[t for t in received if (t.get('description') or '').strip()=='Work Dinner']
print('work_received_count', len(work_received))
for t in sorted(work_received, key=lambda x: x.get('created_at') or ''):
    s=t.get('sender') or {}
    print('tx', t.get('transaction_id'), 'amount', t.get('amount'), 'sender_email', s.get('email'), 'sender_name', s.get('name'), 'created_at', t.get('created_at'))

# Determine paid shares by sender name containment + amount
paid_names=set()
from collections import defaultdict
paid_cents=defaultdict(int)
for t in work_received:
    sender=(t.get('sender') or {})
    sname=(sender.get('name') or '').strip().lower()
    amt=float(t.get('amount') or 0.0)
    paid_cents[sname]+=int(round(amt*100))

owed_cents={s['name'].strip().lower(): s['cents'] for s in shares}
for sname, owed in owed_cents.items():
    if paid_cents.get(sname,0) >= owed:
        paid_names.add(sname)

unpaid=[s for s in shares if s['name'].strip().lower() not in paid_names]
print('unpaid_by_name', [(u['name'], u['amount']) for u in unpaid])

# Get coworker emails matching unpaid first names
relationships=apis.phone.show_contact_relationships(access_token=phone_access)
rel='coworker'
contacts=[]
page=0
while True:
    resp=apis.phone.search_contacts(access_token=phone_access, relationship=rel, page_index=page, page_limit=20)
    if not resp:
        break
    if isinstance(resp, dict) and 'message' in resp:
        raise RuntimeError(resp['message'])
    contacts.extend(resp)
    if len(resp)<20:
        break
    page+=1

unpaid_firsts=set([u['name'].strip().lower() for u in unpaid])
lookup={}
for c in contacts:
    fn=(c.get('first_name') or '').strip().lower()
    if fn in unpaid_firsts:
        # if duplicates, keep all; but likely one
        lookup.setdefault(fn, []).append(c)

print('matched_contact_emails', {k:[x.get('email') for x in v] for k,v in lookup.items()})

# For each unpaid, verify no work_received tx exists with matching sender email/amount
# We'll use first matched contact per first_name.
result=[]
for u in unpaid:
    first=u['name'].strip().lower(); owed_c=u['cents']
    matched_emails=lookup.get(first,[])
    if not matched_emails:
        print('WARN no contact for', u['name'])
        continue
    # check any received tx with any matching sender email and amount cents
    already=False
    for c in matched_emails:
        em=c.get('email')
        for t in work_received:
            s=(t.get('sender') or {})
            if (s.get('email') or '').strip().lower()==(em or '').strip().lower():
                if int(round(float(t.get('amount') or 0.0)*100))==owed_c:
                    already=True
    result.append((u['name'], u['amount'], [c.get('email') for c in matched_emails], already))

print('verification_unpaid', result)

